import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';

const COMPANY_NAMES = {
  AAPL:'Apple Inc.',MSFT:'Microsoft Corp.',GOOGL:'Alphabet Inc.',
  TSLA:'Tesla Inc.',AMZN:'Amazon.com Inc.',META:'Meta Platforms',
  NVDA:'NVIDIA Corp.',JPM:'JPMorgan Chase',
};

const PredictionCard = ({ prediction }) => {
  const { ticker, timestamp, current_price, predicted_price,
          direction, change_percent, confidence, regime } = prediction;

  const isUp = direction?.includes('UP');
  const [confWidth, setConfWidth] = useState(0);

  useEffect(() => {
    const t = setTimeout(() => setConfWidth(confidence * 100), 200);
    return () => clearTimeout(t);
  }, [confidence]);

  const fmt = iso => new Date(iso).toLocaleString('en-US', {
    month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'
  });

  const regimeCls = regime?.regime_name
    ? `regime-${regime.regime_name.toLowerCase()}`
    : '';

  return (
    <motion.div
      className="prediction-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45 }}
    >
      {/* Top row */}
      <div className="pred-top">
        <div className="pred-ticker-wrap">
          <div className="prediction-ticker">{ticker}</div>
          <div className="pred-company">{COMPANY_NAMES[ticker] || ticker}</div>
          <div className="prediction-timestamp">{fmt(timestamp)}</div>
        </div>
        <div className={`direction-badge ${isUp ? 'up' : 'down'}`}>
          <span className="dir-arrow">{isUp ? '↑' : '↓'}</span>
          <span>{isUp ? 'BULLISH' : 'BEARISH'}</span>
        </div>
      </div>

      {/* Price boxes */}
      <div className="prediction-prices">
        <motion.div className="price-box" initial={{ opacity:0,x:-16 }} animate={{ opacity:1,x:0 }} transition={{ delay:0.1 }}>
          <div className="price-label">Current Price</div>
          <div className="price-value current">${current_price.toFixed(2)}</div>
        </motion.div>

        <motion.div className="price-box" initial={{ opacity:0,x:-16 }} animate={{ opacity:1,x:0 }} transition={{ delay:0.18 }}>
          <div className="price-label">Predicted Price</div>
          <div className="price-value predicted">${predicted_price.toFixed(2)}</div>
        </motion.div>

        <motion.div className="price-box" initial={{ opacity:0,x:-16 }} animate={{ opacity:1,x:0 }} transition={{ delay:0.26 }}>
          <div className="price-label">Expected Change</div>
          <div className={`price-value ${isUp ? 'up' : 'down'}`}>
            {change_percent >= 0 ? '+' : ''}{change_percent.toFixed(2)}%
          </div>
        </motion.div>

        <motion.div className="price-box" initial={{ opacity:0,x:-16 }} animate={{ opacity:1,x:0 }} transition={{ delay:0.34 }}>
          <div className="price-label">Market Regime</div>
          <div className={`price-value ${regimeCls}`}>
            {regime?.regime_name || '—'}
          </div>
        </motion.div>
      </div>

      {/* Confidence bar */}
      <div>
        <div className="conf-header">
          <span className="conf-label">Model Confidence</span>
          <span className="conf-value">{(confidence * 100).toFixed(1)}%</span>
        </div>
        <div className="confidence-progress">
          <div className="confidence-fill" style={{ width: `${confWidth}%` }} />
        </div>
      </div>
    </motion.div>
  );
};

export default PredictionCard;
